import string

def scramble_word(word):
    """Scramble a word by swapping adjacent characters."""
    scrambled = list(word)
    for i in range(len(scrambled) - 1):
        if scrambled[i] == scrambled[i + 1]:
            scrambled[i], scrambled[i + 1] = scrambled[i + 1], scrambled[i]
    return ''.join(scrambled)

def unscramble_word(scrambled_word):
    """Unscramble a word by swapping adjacent characters."""
    word = list(scrambled_word)
    for i in range(len(word) - 1):
        if word[i] == word[i + 1]:
            word[i], word[i + 1] = word[i + 1], word[i]
    return ''.join(word)

def main():
    scrambled_word = input("Enter a scrambled word: ")
    unscrambled_word = unscramble_word(scramble_word(scrambled_word))
    print(f"Unscramble the word: {unscrambled_word}")

# Ensure the program only runs when called directly
if __name__ == "__main__":
    main()
